/**
 * Installable offline app. The service worker (generated by vite-plugin-pwa /
 * Workbox) precaches the built files, so the editor opens without a network.
 * Updates wait for the user to choose "Reload" so unsaved typing isn't lost.
 */
import { registerSW } from 'virtual:pwa-register';
import { byId } from '../ui/dom';
import { showToast } from '../ui/toast';

interface InstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

export function initPwa(): void {
  if (!('serviceWorker' in navigator)) return;

  const update = registerSW({
    onNeedRefresh() {
      showToast('A new version of SASU Invoice is ready', 'ok', {
        label: 'Reload',
        run: () => void update(true),
      });
    },
    onOfflineReady() {
      showToast('Ready to work offline');
    },
  });

  const installBtn = byId<HTMLButtonElement>('installBtn');
  let deferred: InstallPromptEvent | null = null;
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferred = e as InstallPromptEvent;
    installBtn.hidden = false;
  });
  installBtn.addEventListener('click', async () => {
    if (!deferred) return;
    await deferred.prompt();
    const { outcome } = await deferred.userChoice;
    deferred = null;
    installBtn.hidden = true;
    if (outcome === 'accepted') showToast('SASU Invoice installed');
  });
  window.addEventListener('appinstalled', () => {
    installBtn.hidden = true;
  });
}
